const e=[{id:"sv-2-841",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"Which is a purpose of basic statistics given in the book?",options:["To prove which X is the root cause of a defect","To set the customer's specification limits","To provide the basis for making inferences about the future","To replace the process map in the Measure phase"],answer:2,hint:"The book lists four purposes: summary, inference, capability foundation, common language.",steps:[{title:"Key idea",body:"Book p. 139: basic statistics provide a numerical summary, **the basis for inferences about the future**, the foundation for capability and a common language."},{title:"Eliminate look-alikes",body:"Root-cause proof, specification setting and process mapping belong to other tools."}],final:"Basis for inferences about the future → answer **C**",whyWrong:["Incorrect — proving root causes is the job of hypothesis tests in Analyze, not of basic statistics.","Incorrect — specification limits come from the voice of the customer, not from statistics.","","Incorrect — process maps and statistics are separate Measure tools; neither replaces the other."],bookRef:"Book p. 139"},{id:"sv-2-842",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"What does the book describe as **the basic language of Six Sigma**?",options:["Process mapping","The project charter","Statistics","Lean waste terms"],answer:2,hint:"What do processes 'speak' in?",steps:[{title:"Key idea",body:'Book p. 139: "Statistics is the basic language of Six Sigma" and the foundation for many later tools.'},{title:"Apply to the stem",body:"Processes speak through data, and statistics is how the team understands them."}],final:"Statistics = basic language → answer **C**",whyWrong:["Incorrect — process maps show how work flows; the book does not call them the basic language.","Incorrect — the charter scopes the project; it is not the language used to describe processes.","","Incorrect — the waste terms describe Lean concepts, not the common analytical language."],bookRef:"Book p. 139"},{id:"sv-2-843",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"According to the book, what lowers the risk of improper decision making?",options:["Decisions based on the experience of senior staff","Collecting as much raw data as possible","Data turned into information and then into knowledge","Agreement reached by a vote in a team meeting"],answer:2,hint:"Raw data must be refined before it helps a decision.",steps:[{title:"Key idea",body:"Book p. 142: data turned into **information**, then transformed into **knowledge**, lowers the risk of improper decisions."},{title:"Eliminate look-alikes",body:"Experience, raw volume and votes are not refined data."}],final:"Data → information → knowledge → answer **C**",whyWrong:['Incorrect — experience alone is the "I think, I feel" practice the book wants replaced by data.',"Incorrect — raw data are like crude oil; volume without refining gives no knowledge.","","Incorrect — a vote is opinion, not data-based knowledge."],bookRef:"Book p. 142"},{id:"sv-2-844",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which does the book name as one of the primary reasons Six Sigma has become popular and effective?",options:["The invention of the Shewhart control chart","The publication of the ISO 9001 standard","The spread of the Toyota Production System","The laptop, with software such as Minitab"],answer:3,hint:"What made the statistics easy for everyone?",steps:[{title:"Key idea",body:"Book p. 140: basic statistics would not be possible without computers and programs like Minitab; the **laptop** is one of the primary reasons Six Sigma became popular."},{title:"Apply to the stem",body:"Software removes the difficulty and time of the analysis."}],final:"Laptop + Minitab → answer **D**",whyWrong:["Incorrect — control charts pre-date Six Sigma by decades; the book credits computers and software.","Incorrect — ISO 9001 is a quality management standard, not the reason the book gives.","Incorrect — the Toyota Production System is the origin of Lean, not the reason the book gives.",""],bookRef:"Book p. 140"},{id:"sv-2-845",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"What is **common cause** variation, in the book's terms?",options:["Variation from unknown factors that gives a steady, random spread around the average","Variation from known factors that gives a non-random distribution of output","Variation added by the gauge each time the same part is measured","Variation that appears only when two different shifts are compared"],answer:0,hint:"Common = unknown factors, random, steady.",steps:[{title:"Key idea",body:"Book p. 158: common cause variation comes from **unknown factors** and gives a **steady but random** distribution around the average."},{title:"Eliminate look-alikes",body:"Known factors and non-random output = special cause; gauge error = measurement variation."}],final:"Common cause = unknown factors, random → answer **A**",whyWrong:["","Incorrect — known factors and a non-random output describe special cause variation.","Incorrect — variation added by the gauge is measurement error, studied in MSA.","Incorrect — a difference between shifts is a known factor, so it points to a special cause."],bookRef:"Book p. 158"},{id:"sv-2-846",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"Which describes **special cause** variation?",options:["Variation that remains after every known factor has been removed","Variation from many small unknown factors acting at random","Variation from known factors that gives a non-random distribution of output","Variation that typically follows a normal distribution"],answer:2,hint:"Special = known factor, non-random pattern.",steps:[{title:"Key idea",body:"Book p. 158: special cause variation is caused by **known factors**, giving a **non-random** distribution of output."},{title:"Eliminate look-alikes",body:"The other three options all describe common cause variation."}],final:"Special cause = known factors, non-random → answer **C**",whyWrong:["Incorrect — what remains after known causes are removed is common cause variation.","Incorrect — many small random unknown factors describe common cause variation.","","Incorrect — the book says common cause variation typically follows a normal distribution."],bookRef:"Book p. 158"},{id:"sv-2-847",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which distribution does common cause variation typically, though not always, follow?",options:["Binomial","Normal","Poisson","Uniform"],answer:1,hint:'The book adds "typically (not always)".',steps:[{title:"Key idea",body:'Book p. 158: common cause variation "typically (not always) follows a **Normal** Distribution".'},{title:"Apply to the stem",body:"That is why a normal shape is expected when only common causes are at work."}],final:"Common cause → typically normal → answer **B**",whyWrong:["Incorrect — the binomial describes pass/fail counts, not the random spread of common causes.","","Incorrect — the Poisson describes counts of defects, not the book's common cause pattern.","Incorrect — a flat uniform shape is not what the book links to common cause variation."],bookRef:"Book p. 158"},{id:"sv-2-848",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"What does the book say special causes represent for an improvement team?",options:["A reason to delete the data","Proof that the gauge is broken","Normal behaviour to be ignored","An opportunity for improvement"],answer:3,hint:'Book slogan: "Special Causes = …"',steps:[{title:"Key idea",body:'Book p. 158: "Special Causes = **Opportunity**" — a known factor the team can act on.'},{title:"Eliminate look-alikes",body:"Deleting, blaming the gauge or ignoring all lose that opportunity."}],final:"Special causes = opportunity → answer **D**",whyWrong:["Incorrect — special causes are investigated, not deleted; they show where gains are.","Incorrect — a special cause is a known process factor; it does not prove a measurement fault.","Incorrect — normal, random behaviour is common cause variation, not special cause.",""],bookRef:"Book p. 158"},{id:"sv-2-849",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"What do **descriptive** statistics do?",options:["Summarise the data actually collected, without claims beyond them","Draw conclusions about a population with a stated level of risk","Predict the result of a future change to the process","Test whether two groups differ by more than chance"],answer:0,hint:"Describe = what these data look like.",steps:[{title:"Key idea",body:"Descriptive statistics (mean, median, s, graphs) summarise the data in hand; nothing is claimed beyond them."},{title:"Eliminate look-alikes",body:"Population conclusions, predictions and tests are inferential."}],final:"Descriptive = summarise the data in hand → answer **A**",whyWrong:["","Incorrect — conclusions about a population with a stated risk are inferential statistics.","Incorrect — predicting the effect of a change goes beyond the data, so it is inferential.","Incorrect — testing whether groups differ beyond chance is a hypothesis test, an inferential tool."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-850",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"What do **inferential** statistics do?",options:["Use a sample to draw conclusions about a population, with a stated risk","Summarise only the values that were actually measured","Sort data into nominal, ordinal, interval or ratio scales","Display the shape of a data set in a histogram"],answer:0,hint:"Infer = go beyond the sample.",steps:[{title:"Key idea",body:"Inferential statistics (confidence intervals, hypothesis tests, regression) conclude about the population or future process with a stated risk such as α."},{title:"Eliminate look-alikes",body:"Summaries and graphs are descriptive; scale classification is a data-type step."}],final:"Inferential = sample → population, with risk → answer **A**",whyWrong:["","Incorrect — summarising only the measured values is descriptive statistics.","Incorrect — classifying scales is data typing, done before any statistics are chosen.","Incorrect — a histogram describes the data in hand, so it is descriptive."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-851",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"In which DMAIC phase does the team rely most heavily on **descriptive** statistics to set the baseline?",options:["Define","Measure","Analyze","Control"],answer:1,hint:"Where is the baseline built?",steps:[{title:"Key idea",body:"Measure describes current performance — centre, spread, shape — to establish the **baseline**."},{title:"Apply to the stem",body:"Inference (tests, regression) dominates Analyze and Improve."}],final:"Descriptive baseline → Measure → answer **B**",whyWrong:["Incorrect — Define scopes the problem; the data baseline is built later.","","Incorrect — Analyze relies mainly on inferential tools such as hypothesis tests.","Incorrect — Control monitors the improved process; the baseline was set earlier."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-852",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"According to the book's notation cheat sheet, most of the notation written in Greek letters refers to what?",options:["Sample data","Population data","Attribute data","Subgroup data"],answer:1,hint:"μ and σ — what do they describe?",steps:[{title:"Key idea",body:'Book p. 140: "most of the notation in Greek is for **population** data" (μ, σ, σ²).'},{title:"Eliminate look-alikes",body:"Sample values use Latin letters: x̄, s, s², p, n."}],final:"Greek = population → answer **B**",whyWrong:["Incorrect — sample statistics use Latin letters such as x̄ and s.","","Incorrect — Greek letters mark population values, whatever the data type.","Incorrect — subgroups use symbols such as x̿ and R̄, not mainly Greek letters."],bookRef:"Book p. 140"},{id:"sv-2-853",phase:2,topic:"2.2.1",qtype:"concept",difficulty:1,stem:"Which is the book's definition of **data**?",options:["Opinions gathered from experienced staff","Conclusions reached by the project team","Factual information organised for analysis","Targets set for the process by the customer"],answer:2,hint:"Data are facts, ready to be analysed.",steps:[{title:"Key idea",body:'Book p. 139: data are "factual information organized for analysis" (also numbers suitable for processing by computer).'},{title:"Eliminate look-alikes",body:"Opinions, conclusions and targets are not factual process information."}],final:"Data = factual information for analysis → answer **C**",whyWrong:['Incorrect — opinions are the "I think, I feel" the book wants replaced by data.',"Incorrect — conclusions are what analysis produces from data, not data themselves.","","Incorrect — customer targets are specifications (VOC), not data about the process."],bookRef:"Book p. 139"},{id:"sv-2-854",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:'How should a Black Belt apply the rule "continuous data is always more desirable" when planning data collection on an assembly line?',options:["By recording only whether each bolt passed, to keep the data simple","By grouping the torque readings into low, medium and high bands","By counting the bolts checked per shift instead of measuring any of them","By recording the measured torque of each bolt rather than only in or out of tolerance"],answer:3,hint:"Keep the measurement, not just the verdict.",steps:[{title:"Key idea",body:"Book p. 146: continuous data give more opportunity for analysis and show how far each unit is from target."},{title:"Apply to the stem",body:"Record the torque value itself; pass/fail can always be derived from it later."}],final:"Record the measured value → answer **D**",whyWrong:["Incorrect — pass/fail is attribute data, the least informative type.","Incorrect — banding turns measurements into ordinal categories and throws information away.","Incorrect — counting checks gives discrete volume data, not the bolts' measured quality.",""],bookRef:"Book p. 146"},{id:"sv-2-855",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which statement about common and special cause variation is CORRECT?",options:["Common cause variation is what remains after special cause variation has been removed","Special cause variation comes from unknown factors acting at random","Common cause variation produces a non-random distribution of output","Special cause variation is also called natural variation"],answer:0,hint:"Remove the special causes — what is left?",steps:[{title:"Key idea",body:'Book p. 158: common cause variation is "the variation left over after Special Cause variation has been removed".'},{title:"Eliminate look-alikes",body:"Each wrong option swaps a common-cause and a special-cause feature."}],final:"Common = what is left after special causes go → answer **A**",whyWrong:["","Incorrect — unknown factors acting at random describe common cause variation.","Incorrect — a non-random distribution points to special causes.","Incorrect — special cause variation is also called assignable cause variation."],bookRef:"Book p. 158"},{id:"sv-2-856",phase:2,topic:"2.2.1",qtype:"concept",difficulty:2,stem:"Which statement about descriptive and inferential statistics is CORRECT?",options:["A descriptive summary needs a confidence level before it is reported","An inferential conclusion always carries a stated level of risk","Inferential statistics describe only the data actually collected","A hypothesis test is a descriptive statistic"],answer:1,hint:"Which one goes beyond the data?",steps:[{title:"Key idea",body:"Inference goes from sample to population, so it is stated with a risk (α or a confidence level)."},{title:"Eliminate look-alikes",body:"Descriptive summaries need no risk statement and claim nothing beyond the data."}],final:"Inference ↔ stated risk → answer **B**",whyWrong:["Incorrect — descriptive summaries make no claim beyond the data, so no risk statement is needed.","","Incorrect — describing only the collected data is descriptive statistics.","Incorrect — a hypothesis test draws a conclusion about a population, so it is inferential."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-857",phase:2,topic:"2.2.1",qtype:"concept",difficulty:3,stem:"Which statement reflects the book's view of data that do not follow the expected normal shape?",options:["If the data are not normal, the measurement system must have failed","If the data are not normal, only common cause variation is present","If the data should be normal but the plots show otherwise, special causes are likely present","If the data are not normal, they should be removed before analysis"],answer:2,hint:"Compare what the data should look like with what they do look like.",steps:[{title:"Key idea",body:'Book p. 158: if the basic structure should be normal but the plots show otherwise, "we know the data contain Special Causes".'},{title:"Apply to the stem",body:"The deviation is an opportunity to investigate."}],final:"Unexpected non-normal → special causes → answer **C**",whyWrong:["Incorrect — non-normal data point first to process special causes, not to a gauge fault.","Incorrect — common cause variation is what typically gives the normal shape.","","Incorrect — the book treats the deviation as a clue to investigate, not data to discard."],bookRef:"Book p. 158"},{id:"sv-2-858",phase:2,topic:"2.2.1",qtype:"concept",difficulty:3,stem:"Which statement about special cause variation reflects the book's advice?",options:["All special causes must be removed before the Measure phase can end","Special causes should stay in the baseline without investigation","Special causes can be found only with a designed experiment","The team need not remove every special cause before starting improvements"],answer:3,hint:'"Biggest bang for your buck."',steps:[{title:"Key idea",body:'Book p. 158: "Do not get too worried about killing all Special Cause variation" — get the biggest gains first by following the method.'},{title:"Eliminate look-alikes",body:"The book does not demand removal of every special cause, nor ignoring them."}],final:"Don't chase every special cause first → answer **D**",whyWrong:["Incorrect — the book says not to worry about killing all special cause variation first.","Incorrect — special causes are opportunities to investigate, not values to leave unexamined.","Incorrect — many special causes are found simply by measuring and describing performance.",""],bookRef:"Book p. 158"},{id:"sv-2-859",phase:2,topic:"2.2.1",qtype:"concept",difficulty:3,stem:"Which statement about defining a population is CORRECT, according to the book?",options:["Unique subsets, such as emerging-market trades, may be defined as a population of their own",'A population should be defined as broadly as possible, such as "all trades"',"A population is defined by the sample that happens to be drawn","A population must never be limited to a single time period"],answer:0,hint:"Careful definition — and unique subsets.",steps:[{title:"Key idea",body:"Book p. 141: define the population carefully; if there are unique subsets of trades it may be appropriate to define those as a unique population."},{title:"Eliminate look-alikes",body:"Broad, sample-led or time-free definitions contradict the book."}],final:"Unique subsets → own population → answer **A**",whyWrong:["","Incorrect — the book asks for a careful, specific definition, e.g. trades completed in 2001.","Incorrect — the population is defined first; the sample is drawn from it, via a frame.","Incorrect — the book's own example limits the population to one year."],bookRef:"Book p. 141"},{id:"sv-2-860",phase:2,topic:"2.2.1",qtype:"statements",difficulty:2,stem:`Which statements about variation are CORRECT?

1. Special cause variation is caused by known factors.
2. Common cause variation typically follows a normal distribution.
3. Common cause variation produces a non-random pattern.
4. Special causes should be ignored because they are rare.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Known → special; random and normal → common.",steps:[{title:"Key idea",body:"Book p. 158: special = known factors, non-random; common = unknown factors, random, typically normal."},{title:"Apply to the stem",body:"Statements 1 and 2 are true; 3 and 4 are false."}],final:"1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 2 is true, but common cause variation is random, not non-random.","Incorrect — both are false: common cause is random, and special causes are opportunities.","Incorrect — statement 1 is true, but special causes are opportunities, not things to ignore."],bookRef:"Book p. 158"},{id:"sv-2-861",phase:2,topic:"2.2.1",qtype:"statements",difficulty:3,stem:`Which statements about kinds of statistics are CORRECT?

1. A descriptive summary must state an alpha level.
2. A 95% confidence interval for all customers is descriptive.
3. A histogram of the sampled call times is descriptive.
4. A hypothesis test on two vendors is inferential.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Does it claim anything beyond the data?",steps:[{title:"Key idea",body:"Descriptive = graphs and summaries of the data in hand; inferential = CIs and tests about the population."},{title:"Apply to the stem",body:"Statements 3 and 4 are true."}],final:"3 and 4 → answer **C**",whyWrong:["Incorrect — both are false: descriptive summaries need no alpha, and a CI for all customers is inferential.","Incorrect — statement 3 is true, but a CI about all customers goes beyond the data: inferential.","","Incorrect — statement 4 is true, but descriptive summaries need no alpha level."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-862",phase:2,topic:"2.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Special cause variation is also referred to as [?] cause variation.`,options:["assignable","chance","common","natural"],answer:0,hint:"A cause you can assign to a known factor.",steps:[{title:"Key idea",body:'Book p. 158: special cause variation "also referred to as **Assignable** Cause".'},{title:"Eliminate look-alikes",body:"Chance, common and natural all describe random, unknown-factor variation."}],final:"Special = assignable → answer **A**",whyWrong:["","Incorrect — chance causes are random, which is common cause variation.","Incorrect — common cause is the opposite of special cause.","Incorrect — natural variability is another name for common cause variation."],bookRef:"Book p. 158"},{id:"sv-2-863",phase:2,topic:"2.2.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Data turned into information, then transformed into [?], lowers the risk of improper decision making.`,options:["evidence","knowledge","opinion","reports"],answer:1,hint:"Data → information → ?",steps:[{title:"Key idea",body:"Book p. 142: data → **information** → **knowledge** lowers the risk of improper decisions."},{title:"Apply to the stem",body:"So the missing word is knowledge."}],final:"knowledge → answer **B**",whyWrong:["Incorrect — the book's chain is data, information, knowledge; evidence is not its term.","","Incorrect — opinion is what the book wants data-based decisions to replace.","Incorrect — reports may carry information, but the book's final step is knowledge."],bookRef:"Book p. 142"},{id:"sv-2-864",phase:2,topic:"2.2.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

[?] statistics use a sample to draw conclusions about a population with a stated level of risk.`,options:["Descriptive","Inferential","Parametric","Summary"],answer:1,hint:"Infer = conclude beyond the sample.",steps:[{title:"Key idea",body:"Inferential statistics go from sample to population and always state a risk (α, confidence)."},{title:"Eliminate look-alikes",body:"Descriptive and summary statistics stay within the data; parametric is a test family."}],final:"Inferential → answer **B**",whyWrong:["Incorrect — descriptive statistics summarise the data in hand without claims beyond them.","","Incorrect — parametric names tests that assume a distribution; it is not the general term here.","Incorrect — summary statistics are descriptive; they carry no risk statement."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-865",phase:2,topic:"2.2.1",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

Common cause variation is the variation left over after [?] cause variation has been removed.`,options:["chance","natural","random","special"],answer:3,hint:"What gets removed first?",steps:[{title:"Key idea",body:"Book p. 158: common cause variation is the variation left over after **Special** Cause variation has been removed."},{title:"Eliminate look-alikes",body:"Chance, natural and random all describe the common cause part that remains."}],final:"special → answer **D**",whyWrong:["Incorrect — chance variation is common cause variation itself, not what is removed.","Incorrect — natural variability is common cause variation, the part that is left.","Incorrect — random variation is what remains, not what is removed.",""],bookRef:"Book p. 158"},{id:"sv-2-866",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:2,stem:"Which is NOT an example of **descriptive** statistics?",options:["The median of the 120 sampled wait times","A 95% confidence interval for the mean wait of all customers","A histogram of the 120 sampled wait times","The range of the 120 sampled wait times"],answer:1,hint:"Which option talks about customers who were not measured?",steps:[{title:"Key idea",body:"Descriptive statistics summarise the data collected; a CI makes a claim about **all** customers with a stated confidence."},{title:"Apply to the stem",body:"So the CI is inferential — the outsider."}],final:"CI for the population = inferential → answer **B**",whyWrong:["Incorrect — the median of the sampled data describes the data in hand.","","Incorrect — a histogram of the sample shows the shape of the data in hand.","Incorrect — the range of the sample is a descriptive spread measure."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-867",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:2,stem:"Which is NOT a feature of **special cause** variation, as the book describes it?",options:["It is caused by known factors","It gives a non-random distribution of output","It is the variation left over after other causes are removed","It is also referred to as assignable cause"],answer:2,hint:"One option is the definition of the other type.",steps:[{title:"Key idea",body:"Book p. 158: special = known factors, non-random, assignable."},{title:"Apply to the stem",body:'"Left over after other causes are removed" defines **common** cause variation.'}],final:"Left-over variation = common cause → answer **C**",whyWrong:["Incorrect — known factors are the book's definition of special causes.","Incorrect — a non-random distribution is a mark of special causes.","","Incorrect — assignable cause is the book's other name for special cause."],bookRef:"Book p. 158"},{id:"sv-2-868",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:3,stem:"Which of these is NOT a discrete variable?",options:["The number of surveys returned out of 300 mailed","The number of defective needles in a box of 100","The number of coin flips needed before the first head","The blood glucose reading of a patient"],answer:3,hint:"Can the value be meaningfully subdivided?",steps:[{title:"Key idea",body:"Book p. 143: counts of returns, defectives and flips are discrete; a glucose reading can take any real value in a range."},{title:"Apply to the stem",body:"The glucose reading is continuous — the outsider."}],final:"Glucose reading = continuous → answer **D**",whyWrong:["Incorrect — surveys returned is a whole-number count from 0 to 300.","Incorrect — defective needles is a whole-number count from 0 to 100.","Incorrect — coin flips is a count with no upper limit, but still whole numbers.",""],bookRef:"Book p. 143"},{id:"sv-2-869",phase:2,topic:"2.2.1",qtype:"not-except",difficulty:3,stem:`A team debates recording each installation's **measured time** instead of only "SLA met / not met". Which argument for the measured time is NOT valid?`,options:["Measured times remove the need for a measurement system analysis","Measured times give more opportunity for statistical analysis","Measured times show how far each job was from the target","Measured times need smaller samples to see the same change"],answer:0,hint:"Does any data type excuse the gauge from checking?",steps:[{title:"Key idea",body:"Book p. 146: continuous data give more opportunity for analysis; they carry distance-from-target information and need smaller samples."},{title:"Apply to the stem",body:"Every measurement system must still pass MSA — continuous data do not remove that need."}],final:"MSA is still needed → answer **A**",whyWrong:["","Incorrect — more opportunity for analysis is the book's stated reason.","Incorrect — distance from target is information pass/fail data cannot give.","Incorrect — more information per point means smaller samples are needed."],bookRef:"Book p. 146",trap:"Any data type still needs a capable measurement system."},{id:"sv-2-870",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:1,stem:"Network latency on a backbone link normally varies randomly around **20 ms**. One afternoon a fibre cut forces traffic onto a longer route and latency jumps for six hours. What type of variation is the jump?",options:["Common cause variation","Special cause variation","Measurement variation","Sampling variation"],answer:1,hint:"Known factor + non-random change = ?",steps:[{title:"Key idea",body:"Book p. 158: special cause variation comes from a **known factor** and gives a non-random pattern."},{title:"Apply to the stem",body:"The fibre cut is a known, assignable event that shifted the output."}],final:"Fibre cut = special cause → answer **B**",whyWrong:["Incorrect — common cause variation is the usual random spread around 20 ms.","","Incorrect — nothing suggests the latency gauge changed; the network itself changed.","Incorrect — sampling variation is chance difference between samples, not a known event."],bookRef:"Book p. 158"},{id:"sv-2-871",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:1,stem:"Daily average handle time in a contact centre moves up and down by about a minute with no pattern. Nothing has changed in staffing, systems or call mix, and no event explains any single day. What does this variation represent?",options:["Special cause variation","Assignable cause variation","Common cause variation","Measurement bias"],answer:2,hint:"No known factor, no pattern.",steps:[{title:"Key idea",body:"Book p. 158: common cause variation comes from **unknown factors** and gives a steady, random spread around the average."},{title:"Apply to the stem",body:"No event, no pattern — this is the process's natural variation."}],final:"Random, no known factor = common cause → answer **C**",whyWrong:["Incorrect — special causes come from known factors and show a non-random pattern.","Incorrect — assignable cause is another name for special cause.","","Incorrect — bias is a constant offset from the true value, not random day-to-day spread."],bookRef:"Book p. 158"},{id:"sv-2-872",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:2,stem:'A Black Belt reports: *"The 120 audited invoices had a median of 3 errors."* The Champion asks her to say instead: *"All invoices issued this year have a median between 2 and 4 errors, with 95% confidence."* What does this change involve?',options:["Moving from inferential to descriptive statistics","Moving from continuous to attribute data","Moving from a population to a sampling frame","Moving from descriptive to inferential statistics"],answer:3,hint:"Which sentence talks about invoices nobody audited?",steps:[{title:"Key idea",body:"The first sentence describes only the 120 invoices; the second concludes about **all** invoices with a stated confidence."},{title:"Apply to the stem",body:"Going from sample summary to population claim = descriptive → inferential."}],final:"Descriptive → inferential → answer **D**",whyWrong:["Incorrect — reversed: the new statement goes beyond the audited invoices.","Incorrect — error counts stay discrete counts in both statements.","Incorrect — both statements concern samples and populations, not a frame.",""],bookRef:"Syllabus 2.2.1"},{id:"sv-2-873",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:2,stem:"A ticket-handling team measures resolution times, describes the current performance with simple statistics and graphs, then makes a few common-sense changes to queue rules. Variation drops sharply before any Analyze tools are used. Which book idea does this illustrate?",options:["Big gains can come from simply measuring, describing performance and making common-sense adjustments","Variation can be reduced only after every special cause is proven with a test","Improvements should wait until the Improve phase in every case","Common sense should be ignored in favour of statistical models"],answer:0,hint:`Recall the book's "ground fruit" remark.`,steps:[{title:"Key idea",body:"Book p. 158: many companies realise BIG gains by simply measuring, describing the performance and then making common-sense adjustments."},{title:"Apply to the stem",body:"The team picked this low-hanging fruit in Measure."}],final:"Measure, describe, adjust → big gains → answer **A**",whyWrong:["","Incorrect — the book says not to worry about killing all special causes before acting.","Incorrect — the book notes many companies gain big early, by measuring and describing.","Incorrect — the book praises common-sense adjustments made after measuring."],bookRef:"Book p. 158"},{id:"sv-2-874",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:3,stem:"A study records how many attempts a customer needs before a call connects: 1, 2, 3 and so on, with no upper limit. A team member argues that, because there is no maximum, the variable must be continuous. What type of variable is it?",options:["Continuous, because it has no upper limit","Discrete, because each value is a whole-number count","Attribute, because each attempt either connects or not","Ordinal, because later attempts come after earlier ones"],answer:1,hint:"Can there be 2.5 attempts?",steps:[{title:"Key idea",body:'Book p. 143: "the number of times you need to flip a coin before a head appears" is discrete, even with no upper limit.'},{title:"Apply to the stem",body:"Attempts are whole-number counts, so the variable is discrete."}],final:"Count with no limit = still discrete → answer **B**",whyWrong:["Incorrect — having no upper limit does not make values subdivisible.","","Incorrect — the recorded value is the number of attempts, not a single yes/no.","Incorrect — the values are counts with equal steps, not ordered categories."],bookRef:"Book p. 143",trap:"No upper limit ≠ continuous; the test is whether values can be subdivided."},{id:"sv-2-875",phase:2,topic:"2.2.1",qtype:"scenario",difficulty:3,stem:'A Black Belt holds six months of daily abandoned-call percentages. The team asks two questions: **(1)** "What did abandonment look like over those six months?" and **(2)** "Will the new IVR menu cut abandonment for all future calls?" Which pairing is correct?',options:["(1) inferential, (2) descriptive","(1) descriptive, (2) descriptive","(1) descriptive, (2) inferential","(1) inferential, (2) inferential"],answer:2,hint:"Which question goes beyond the data held?",steps:[{title:"Key idea",body:"Describing data already held = descriptive; concluding about future or unmeasured calls = inferential."},{title:"Apply to the stem",body:"Question 1 is descriptive; question 2 is inferential."}],final:"(1) descriptive, (2) inferential → answer **C**",whyWrong:["Incorrect — reversed: question 1 summarises existing data, question 2 predicts the future.","Incorrect — question 2 concludes about future calls, which needs inference and a stated risk.","","Incorrect — question 1 only summarises data already held, so it is descriptive."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-876",phase:2,topic:"2.2.1",qtype:"best-action",difficulty:2,stem:"A baseline of ticket resolution times includes three days when the ITSM tool was down and tickets queued for hours. The outage is logged and confirmed. What is the BEST action?",options:["Delete the three days without any record so the baseline looks normal","Keep the days in the baseline and treat them as common cause variation","Stop the project because the process is out of control","Record the outage days as special causes and analyse them separately from the baseline"],answer:3,hint:"Known factor → special cause → handle it separately.",steps:[{title:"Key idea",body:"Book p. 158: special causes are known factors and an **opportunity**."},{title:"Apply to the stem",body:"Document them and analyse them apart from the common cause baseline, so neither picture is distorted."}],final:"Document and separate special causes → answer **D**",whyWrong:["Incorrect — deleting without a record hides an opportunity and loses evidence.","Incorrect — a logged outage is a known factor, so it is special, not common cause.","Incorrect — a known special cause is an opportunity to act on, not a reason to stop.",""],bookRef:"Book p. 158"},{id:"sv-2-877",phase:2,topic:"2.2.1",qtype:"best-action",difficulty:3,stem:'A Black Belt summarised **60** sampled installations (mean **2.4 h**) and told the steering committee: *"All installations next quarter will average 2.4 hours."* Was this an appropriate statement?',options:["Yes, because a sample mean always equals the population mean","Yes, because a sample of 60 is large enough to be certain","No, because a claim about future installations is inferential and needs a stated risk","No, because descriptive statistics cannot be calculated from a sample"],answer:2,hint:"What does a claim about the future need?",steps:[{title:"Key idea",body:"Describing 60 installations is descriptive; claiming what **all future** installations will do is inferential."},{title:"Apply to the stem",body:"An inferential claim needs a stated risk, e.g. a confidence interval, not a bare point value."}],final:"Future claim → inferential, needs risk → answer **C**",whyWrong:["Incorrect — a sample mean estimates the population mean; it rarely equals it exactly.","Incorrect — no sample size gives certainty; inference always carries risk.","","Incorrect — descriptive statistics are routinely calculated from samples."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-878",phase:2,topic:"2.2.1",qtype:"best-action",difficulty:3,stem:"Daily handle time moves randomly within its usual range and no special cause has been found. A manager wants to change staffing every morning to react to the previous day's figure. What is the BEST response from the Black Belt?",options:["Explain that this is common cause variation, so daily reactions add variation; improve the system instead","Agree, because every daily change has a known cause that must be corrected","Agree, but only on days when handle time is above the average","Ask the vendor to explain each day's figure as a special cause"],answer:0,hint:"Reacting to noise as if it were a signal.",steps:[{title:"Key idea",body:"Book p. 158: common cause variation is random, from unknown factors; it is not explained point by point."},{title:"Apply to the stem",body:"Adjusting after every point (tampering) adds variation; reduce common cause by changing the process itself."}],final:"Don't treat common cause as special → answer **A**",whyWrong:["","Incorrect — random day-to-day movement with no known factor is common cause, not special cause.","Incorrect — reacting to every above-average day still treats common cause as special.","Incorrect — common cause days have no assignable cause to explain."],bookRef:"Book p. 158"},{id:"sv-2-879",phase:2,topic:"2.2.1",qtype:"best-action",difficulty:2,stem:"A quality team has a raw log in which each inspected panel is marked only **Pass** or **Fail**. The book says no analysis can be performed on attribute data in this form. What should the team do FIRST?",options:["Run a hypothesis test directly on the Pass and Fail labels","Count the results, for example fails per batch, to turn them into discrete data","Rank the panels from best to worst on an ordinal scale","Calculate the standard deviation of the Pass and Fail labels"],answer:1,hint:"What turns binary labels into something usable?",steps:[{title:"Key idea",body:'Book p. 142: attribute data "must be converted to a form of variable data called discrete data in order to be counted or be useful".'},{title:"Apply to the stem",body:"Counting fails per batch (or per day) creates discrete data that can be analysed."}],final:"Count attribute data first → answer **B**",whyWrong:["Incorrect — a test needs counts or proportions; labels must be counted first.","","Incorrect — Pass/Fail cannot be ranked into more levels without new measurements.","Incorrect — labels have no numeric value, so a standard deviation is meaningless."],bookRef:"Book p. 142"},{id:"sv-2-880",phase:2,topic:"2.2.1",qtype:"output",difficulty:2,stem:`A contact-centre log of daily mean handle time:

\`\`\`
Day   MeanAHT(min)   Log note
Mon       6.1        –
Tue       5.9        –
Wed       6.3        –
Thu       9.8        CRM outage 10:00–14:00
Fri       6.0        –
\`\`\`

Which conclusion is CORRECT?`,options:["All five days reflect common cause variation, because the week is short","Thursday proves the process is not capable of meeting the target","Thursday reflects special cause variation from a known factor; the other days reflect common cause","Monday to Friday except Thursday show special cause variation"],answer:2,hint:"Match the log note to a known factor.",steps:[{title:"Key idea",body:"Book p. 158: special cause = known factor, non-random; common cause = unknown factors, random."},{title:"Apply to the stem",body:"The CRM outage is a known factor behind Thursday's jump; the others vary randomly around 6 min."}],final:"Thursday = special cause → answer **C**",whyWrong:["Incorrect — Thursday has a logged, known cause and a clear jump, which marks a special cause.","Incorrect — capability needs specifications and a stable process; the log shows neither.","","Incorrect — the small random movement on the other days is common cause variation."],bookRef:"Book p. 158"},{id:"sv-2-881",phase:2,topic:"2.2.1",qtype:"output",difficulty:2,stem:`Minitab output for customer wait times:

\`\`\`
Descriptive Statistics: WaitSec
Variable   N    Mean   StDev   Median
WaitSec    85  142.3    61.7    128.0

95% Confidence Interval for Mean: (129.0, 155.6)
\`\`\`

Which value is an **inferential** statistic?`,options:["The median of 128.0","The standard deviation of 61.7","The sample size of 85","The 95% confidence interval for the mean"],answer:3,hint:"Which line speaks about the population?",steps:[{title:"Key idea",body:"The confidence interval estimates the **population** mean with a stated confidence (95%), so it is inferential."},{title:"Eliminate look-alikes",body:"Median, StDev and N summarise the sample: descriptive."}],final:"95% CI = inferential → answer **D**",whyWrong:["Incorrect — the median describes the 85 sampled waits only.","Incorrect — StDev describes the spread of the 85 sampled waits only.","Incorrect — N simply counts the values collected.",""],bookRef:"Syllabus 2.2.1"},{id:"sv-2-882",phase:2,topic:"2.2.1",qtype:"output",difficulty:2,stem:`Defects recorded on two packing shifts last week:

\`\`\`
Shift   Defects   Hours worked   Defects per hour
A          48          8              6.0
B          48         12              4.0
\`\`\`

Which conclusion is CORRECT?`,options:["The raw counts are equal, but the rate shows Shift A performs worse","The shifts perform the same because the defect counts are equal","Shift B performs worse because it worked more hours","The rate cannot be used because defects are attribute data"],answer:0,hint:"Read the rate column, not the count column.",steps:[{title:"Key idea",body:'Book p. 146: "200 defects or 25 defects/hour" — a rate is more useful than a raw count.'},{title:"Apply to the stem",body:"Shift A shows 6.0 defects per hour against 4.0 for B."}],final:"Rate shows A is worse → answer **A**",whyWrong:["","Incorrect — equal counts over unequal hours hide a different defect rate.","Incorrect — the printed rate is lower for Shift B, so B performs better.","Incorrect — the book recommends converting counts to a rate, e.g. defects per hour."],bookRef:"Book p. 146"},{id:"sv-2-883",phase:2,topic:"2.2.1",qtype:"output",difficulty:2,stem:`Minitab tally of a first-time-fix field:

\`\`\`
Tally for Discrete Variables: FirstTimeFix
FirstTimeFix   Count   Percent
No                37     18.50
Yes              163     81.50
N=               200
\`\`\`

Which statement is CORRECT?`,options:["The data are continuous, because the percentages have decimals","Counting the Yes/No results has turned attribute data into discrete data that can be analysed","The tally is an inferential statistic about all future repairs","The data are ordinal, because No is listed before Yes"],answer:1,hint:"What did the tally do to the Yes/No labels?",steps:[{title:"Key idea",body:"Book p. 142: attribute data must be converted to discrete data (counted) to be useful."},{title:"Apply to the stem",body:"The tally counts 37 No and 163 Yes — discrete counts that can now be analysed."}],final:"Tally turns attribute into counts → answer **B**",whyWrong:["Incorrect — each raw value is Yes or No; decimals in a summary do not make data continuous.","","Incorrect — the tally only describes the 200 repairs recorded.","Incorrect — Yes/No has no order; the listing is alphabetical."],bookRef:"Book p. 142"},{id:"sv-2-884",phase:2,topic:"2.2.1",qtype:"output",difficulty:3,stem:`A Black Belt compared two summaries of the same 400 broadband installations:

\`\`\`
Summary                         Reported value
SLA met (yes/no)                 92% met
Install time, minutes            Mean 74, StDev 31, Max 260
\`\`\`

Which conclusion does the comparison support?`,options:["The yes/no summary carries more information because it is a percentage","Both summaries carry the same information about the process","The install times show how far each job ran, which the yes/no summary cannot show","The install times should be discarded because the SLA result is known"],answer:2,hint:"Which line tells you 'by how much'?",steps:[{title:"Key idea",body:"Book p. 146: continuous data is always more desirable — it shows how far each unit is from target."},{title:"Apply to the stem",body:'Mean, StDev and Max reveal spread and the long tail; "92% met" hides them.'}],final:"Continuous shows 'how far' → answer **C**",whyWrong:["Incorrect — the percentage is built from binary data, the least informative type.","Incorrect — only the times show spread and how late the worst jobs were.","","Incorrect — discarding the continuous data throws away the most useful information."],bookRef:"Book p. 146"},{id:"sv-2-885",phase:2,topic:"2.2.1",qtype:"true-false",difficulty:3,stem:"Common cause variation always follows a normal distribution. True or False?",options:["True","False"],answer:1,hint:'Watch the word "always".',steps:[{title:"Key idea",body:'Book p. 158: common cause variation "typically (**not always**) follows a Normal Distribution".'},{title:"Apply to the stem",body:'"Always" makes the statement false.'}],final:"False → answer **False**",whyWrong:["Incorrect — the book says common cause variation typically, not always, follows a normal distribution.",""],bookRef:"Book p. 158"},{id:"sv-2-886",phase:2,topic:"2.2.1",qtype:"sequence",difficulty:1,stem:`Put these stages in the order the book uses to describe how data support better decisions.

- **P** Information
- **Q** Knowledge
- **R** Data
- **S** Decision`,options:["P → R → Q → S","R → Q → P → S","Q → P → R → S","R → P → Q → S"],answer:3,hint:"Crude oil is refined step by step.",steps:[{title:"Key idea",body:"Book p. 142: data turned into information, then transformed into knowledge, lowers decision risk."},{title:"Apply to the stem",body:"So data → information → knowledge → decision: R, P, Q, S."}],final:"R → P → Q → S → answer **D**",whyWrong:["Incorrect — information is produced from data, so data come first.","Incorrect — knowledge is built from information, not the other way round.","Incorrect — reversed: knowledge is the last refinement before the decision.",""],bookRef:"Book p. 142"},{id:"sv-2-887",phase:2,topic:"2.2.1",qtype:"sequence",difficulty:2,stem:`Order the book's quick-win path that lets many companies reduce variation early.

- **P** Make common-sense adjustments within the process
- **Q** Measure the process
- **R** Describe the performance`,options:["Q → R → P","R → Q → P","P → Q → R","Q → P → R"],answer:0,hint:"Measure, then describe, then act.",steps:[{title:"Key idea",body:'Book p. 158: many companies realise BIG gains "by simply measuring, describing the performance and then making common sense adjustments".'},{title:"Apply to the stem",body:"So Q, R, P."}],final:"Q → R → P → answer **A**",whyWrong:["","Incorrect — performance cannot be described before it has been measured.","Incorrect — adjusting first is acting on opinion, not on data.","Incorrect — adjustments should follow a description of the performance."],bookRef:"Book p. 158"},{id:"sv-2-888",phase:2,topic:"2.2.1",qtype:"sequence",difficulty:2,stem:`Order these steps for moving from a sample to a conclusion about the population.

- **P** State the conclusion about the population with its risk
- **Q** Describe the sample's centre, spread and shape
- **R** Choose the inferential tool the description supports
- **S** Collect the sample`,options:["S → R → Q → P","S → Q → R → P","Q → S → R → P","S → Q → P → R"],answer:1,hint:"Descriptive first, inferential second.",steps:[{title:"Key idea",body:"A careful description (shape, outliers) tells you which inferential tool is valid."},{title:"Apply to the stem",body:"Collect → describe → choose the tool → conclude with risk: S, Q, R, P."}],final:"S → Q → R → P → answer **B**",whyWrong:["Incorrect — the tool is chosen after the description shows shape and outliers.","","Incorrect — there is nothing to describe until the sample has been collected.","Incorrect — the conclusion comes from the tool, so the tool is chosen first."],bookRef:"Syllabus 2.2.1"},{id:"sv-2-889",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"According to the book, what should a Black Belt ask about the mean, median and mode of a new data set?",options:["Which of them is largest, so it can be reported as the baseline","Whether they fall inside the specification limits","How alike or different they are, and what that tells us","Which of them has the smallest standard deviation"],answer:2,hint:"The book's three descriptive questions.",steps:[{title:"Key idea",body:"Book p. 147: for the measures of location (and of variation), ask how alike or different they are, and what the similarities or differences tell us."},{title:"Apply to the stem",body:"For example, a mean far above the median signals a few large values."}],final:"Compare the measures of location → answer **C**",whyWrong:["Incorrect — the largest measure is not automatically the right baseline; the comparison is what informs.","Incorrect — comparing with specifications is capability analysis, not descriptive statistics.","","Incorrect — location measures do not have their own standard deviations to compare."],bookRef:"Book p. 147"},{id:"sv-2-890",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What is the **median** of a data set?",options:["The arithmetic balance point of the data","The value that occurs most often","The average of the largest and smallest values","The middle value, or 50th percentile, of the ordered data"],answer:3,hint:"Sort the data, then look in the middle.",steps:[{title:"Key idea",body:"Book p. 148: the median is the mid-point, or **50th percentile**, of the ordered data."},{title:"Eliminate look-alikes",body:"Balance point = mean; most frequent = mode."}],final:"Median = 50th percentile → answer **D**",whyWrong:["Incorrect — the balance point is the mean.","Incorrect — the most frequent value is the mode.","Incorrect — the median uses the middle of the ordered data, not the two extremes.",""],bookRef:"Book p. 148"},{id:"sv-2-891",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What is the **mode** of a data set?",options:["The most frequently occurring value","The middle value of the ordered data","The average after removing the extremes","The difference between the largest and smallest values"],answer:0,hint:"Mode = most popular.",steps:[{title:"Key idea",body:"Book p. 149: the mode is the **most frequently occurring** value in a distribution."},{title:"Eliminate look-alikes",body:"Median = middle; trimmed mean = average without extremes; range = spread."}],final:"Mode = most frequent → answer **A**",whyWrong:["","Incorrect — the middle value of the ordered data is the median.","Incorrect — the average after removing extremes is the trimmed mean.","Incorrect — the largest minus the smallest value is the range, a spread measure."],bookRef:"Book p. 149"},{id:"sv-2-892",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"How do the causes behind a distribution with **multiple modes** compare with those of other non-normal shapes, according to the book?",options:["They are usually the hardest causes to identify","They are usually the easiest causes to identify","They can be found only with a designed experiment","They are always caused by measurement error"],answer:1,hint:'The book says "Celebrate!"',steps:[{title:"Key idea",body:'Book p. 261: multiple modes come from such dramatic combinations of sources that they show distinct modes — "These are usually the easiest to identify causes."'},{title:"Eliminate look-alikes",body:"Most likely reason: a mixture of distributions."}],final:"Multiple modes → easiest causes to find → answer **B**",whyWrong:["Incorrect — reversed: separate modes make the underlying sources stand out.","","Incorrect — distinct modes can often be traced by simple stratification of existing data.","Incorrect — the book's most likely reason is a mixture of distributions, not the gauge."],bookRef:"Book p. 261"},{id:"sv-2-893",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Why does the book say average salary is usually reported as a **median**?",options:["The median is easier to calculate than the mean","Salaries are attribute data, so a mean cannot be calculated","A few very high earners pull the mean up, but not the median","The median always equals the most common salary"],answer:2,hint:"Think of a billionaire joining the data set.",steps:[{title:"Key idea",body:"Book p. 148: the median is unaffected by large data values; people like Bill Gates **skew the average**."},{title:"Apply to the stem",body:"So a typical salary is better shown by the median."}],final:"Median resists extremes → answer **C**",whyWrong:["Incorrect — the reason is resistance to extremes, not ease of calculation.","Incorrect — salaries are continuous (money), so a mean can be calculated; it is just misleading.","","Incorrect — the most common salary is the mode, which can differ from the median."],bookRef:"Book p. 148"},{id:"sv-2-894",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What does the book call a distribution that has **two modes**?",options:["Bimodal","Leptokurtic","Platykurtic","Skewed"],answer:0,hint:"Bi = two.",steps:[{title:"Key idea",body:"Book p. 149: when there are multiple modes it is called a **bi-modal** distribution."},{title:"Eliminate look-alikes",body:"Lepto/platykurtic describe tails; skewed describes asymmetry."}],final:"Two modes = bimodal → answer **A**",whyWrong:["","Incorrect — leptokurtic describes a peaked shape with long tails, not two peaks.","Incorrect — platykurtic describes a flat shape with short tails.","Incorrect — skewed describes a long tail on one side, not two peaks."],bookRef:"Book p. 149"},{id:"sv-2-895",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"According to the book, when is a **trimmed mean** most useful?",options:["When the data are binary pass/fail results","When only two observations are available","When the most frequent value is needed","When the data may contain extreme values"],answer:3,hint:"What is trimmed off, and why?",steps:[{title:"Key idea",body:'Book p. 149: the trimmed mean is "useful for data with potential extreme values" and is less susceptible to extreme scores.'},{title:"Eliminate look-alikes",body:"Binary data, two-value samples and 'most frequent' call for other measures."}],final:"Trimmed mean → possible extremes → answer **D**",whyWrong:["Incorrect — pass/fail data are attribute data and are summarised as counts or proportions.","Incorrect — with two values there is nothing to trim; the range is fully efficient there.","Incorrect — the most frequent value is the mode.",""],bookRef:"Book p. 149"},{id:"sv-2-896",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which measures of variation does the book recommend when the data distribution is **skewed**?",options:["Range or interquartile range","Standard deviation or variance","Variance or standard error of the mean","Standard deviation or coefficient of variation"],answer:0,hint:"Skewed → use measures based on order, not on the mean.",steps:[{title:"Key idea",body:'Book p. 150: "Use Range or Interquartile Range when the data distribution is Skewed."'},{title:"Eliminate look-alikes",body:"Standard deviation (and measures built on it) is for symmetrical data."}],final:"Skewed → range or IQR → answer **A**",whyWrong:["","Incorrect — the book reserves the standard deviation for symmetrical data.","Incorrect — both depend on squared deviations from the mean, which a long tail inflates.","Incorrect — both are built on the standard deviation, which suits symmetrical data."],bookRef:"Book p. 150"},{id:"sv-2-897",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"In the book's example of a mixed distribution, two data sets combine into one skewed distribution. What shape did each source data set have before they were combined?",options:["Skewed","Normal","Bimodal","Platykurtic"],answer:1,hint:"Mixing can create a shape neither source has.",steps:[{title:"Key idea",body:'Book p. 257: "both distributions that formed the combined Skewed Distribution started out as Normal Distributions."'},{title:"Apply to the stem",body:"A non-normal summary shape can come from mixing normal sources, so stratify before concluding."}],final:"Sources were normal; mixture made the skew → answer **B**",whyWrong:["Incorrect — the skew appears only after the two sources are combined.","","Incorrect — each source had a single peak; two peaks arise only when sources are far apart.","Incorrect — a flat shape is not how the book describes the two sources."],bookRef:"Book p. 257"},{id:"sv-2-898",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"How is the median found when the ordered data set has an **odd** number of observations?",options:["It is the average of the two middle values","It is the most frequently occurring value","It is the single middle value of the ordered list","It is the average of the smallest and largest values"],answer:2,hint:"Odd count → one value sits exactly in the middle.",steps:[{title:"Key idea",body:"Book p. 148: with an odd number of observations the median is **the single middle value**; with an even number it is the average of the two middle values."},{title:"Eliminate look-alikes",body:"Mode = most frequent; extremes play no part in the median."}],final:"Odd n → single middle value → answer **C**",whyWrong:["Incorrect — averaging the two middle values is the rule for an even number of observations.","Incorrect — the most frequent value is the mode.","","Incorrect — the midpoint of the extremes depends on the extremes; the median does not."],bookRef:"Book p. 148"},{id:"sv-2-899",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Which describes the **variance**?",options:["The typical distance of the data points from the mean, in data units","The difference between the largest and smallest values","The difference between the 75th and 25th percentiles","The average squared deviation of each data point from the mean"],answer:3,hint:"Squared deviations, averaged.",steps:[{title:"Key idea",body:"Book p. 150: variance is the **average squared deviation** of each data point from the mean; it is the square of the standard deviation."},{title:"Eliminate look-alikes",body:"SD = data-unit distance; range = max − min; IQR = Q3 − Q1."}],final:"Variance = average squared deviation → answer **D**",whyWrong:["Incorrect — the typical distance in data units is the standard deviation.","Incorrect — largest minus smallest is the range.","Incorrect — the 75th minus the 25th percentile is the interquartile range.",""],bookRef:"Book p. 150"},{id:"sv-2-900",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"Which book cause of skewness arises when product outside a specification limit is removed before the data are recorded?",options:["Artificial limits (sorting)","Natural limits","Interactions","Non-random patterns across time"],answer:0,hint:"Someone cut off part of the distribution.",steps:[{title:"Key idea",body:"Book p. 257 lists causes of skewness: natural limits, **artificial limits (sorting)**, mixtures, non-linear relationships, interactions, non-random patterns across time."},{title:"Apply to the stem",body:"Scrapping out-of-spec parts before measuring truncates one side — an artificial limit."}],final:"Sorting = artificial limit → answer **A**",whyWrong:["","Incorrect — a natural limit is a physical bound, such as a time that cannot be below zero.","Incorrect — interactions are effects of factors acting together, not removal of values.","Incorrect — patterns across time are trends or cycles, not a cut made by inspection."],bookRef:"Book p. 257"},{id:"sv-2-901",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"What does **kurtosis** describe?",options:["The direction in which the longest tail points","The shape of the tails and peak of a distribution","The location of the centre of the data","The number of modes in the data"],answer:1,hint:"Lepto- and platy- refer to it.",steps:[{title:"Key idea",body:'Book p. 260: kurtosis "refers to the shape of the tails" — leptokurtic (peaked, long tails) or platykurtic (flat, short tails).'},{title:"Eliminate look-alikes",body:"Skewness = tail direction; mean/median = centre; modes = peaks."}],final:"Kurtosis = tails/peakedness → answer **B**",whyWrong:["Incorrect — the direction of the long tail is described by skewness.","","Incorrect — the centre is described by the mean, median or mode.","Incorrect — the number of peaks is described as uni-, bi- or multimodal."],bookRef:"Book p. 260"},{id:"sv-2-902",phase:2,topic:"2.2.2",qtype:"concept",difficulty:3,stem:"According to the book, which can cause a **leptokurtic** distribution?",options:["Several means shifting over time, producing a plateau","A single stable process with only random error","Distributions with very different variances overlaying each other","Two process means far enough apart to form separate peaks"],answer:2,hint:"Narrow and wide distributions stacked together.",steps:[{title:"Key idea",body:'Book p. 261: "Distributions overlaying each other that have very different variance can cause a Leptokurtic distribution."'},{title:"Eliminate look-alikes",body:"Shifting means → platykurtic; separated means → bimodal; random error only → normal."}],final:"Different variances overlaid → leptokurtic → answer **C**",whyWrong:["Incorrect — shifting means that form a plateau give a platykurtic shape.","Incorrect — a stable process with only random error gives a normal shape.","","Incorrect — well-separated means produce multiple modes (bimodal), not long tails."],bookRef:"Book p. 261"},{id:"sv-2-903",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Which Minitab descriptive statistics column reports the **trimmed mean**?",options:["Mean","Median","SE Mean","TrMean"],answer:3,hint:"Minitab abbreviates it.",steps:[{title:"Key idea",body:"Book p. 149: choose Trimmed Mean in *Display Descriptive Statistics*; Minitab prints it as **TrMean**."},{title:"Eliminate look-alikes",body:"Mean, Median and SE Mean are different statistics."}],final:"TrMean = trimmed mean → answer **D**",whyWrong:["Incorrect — Mean is the ordinary average of all values.","Incorrect — Median is the 50th percentile of the ordered data.","Incorrect — SE Mean is the standard error of the mean, a measure of precision.",""],bookRef:"Book p. 149"},{id:"sv-2-904",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Mean, median and mode belong to which family of descriptive statistics?",options:["Measures of variation (dispersion)","Measures of shape (skewness and kurtosis)","Measures of capability (Cp and Cpk)","Measures of location (central tendency)"],answer:3,hint:"Where is the centre?",steps:[{title:"Key idea",body:"Book p. 147: measures of **location** (central tendency) — mean, median, mode; measures of variation — range, IQR, SD, variance."},{title:"Eliminate look-alikes",body:"Shape and capability are other families."}],final:"Mean/median/mode = location → answer **D**",whyWrong:["Incorrect — range, IQR, standard deviation and variance are the measures of variation.","Incorrect — skewness and kurtosis describe shape, not the centre.","Incorrect — capability indices compare the process with its specifications.",""],bookRef:"Book p. 147"},{id:"sv-2-905",phase:2,topic:"2.2.2",qtype:"concept",difficulty:1,stem:"Which graph does the book request alongside *Display Descriptive Statistics* to see the shape of the data?",options:["A histogram of the data, with a normal curve","A Pareto chart of the data, sorted by frequency","A control chart of the data, with limits","A scatterplot of the data against time"],answer:0,hint:"Minitab: Display Descriptive Statistics > Graphs.",steps:[{title:"Key idea",body:"Book p. 148: *Stat > Basic Statistics > Display Descriptive Statistics… > Graphs… > Histogram of data, with normal curve*."},{title:"Apply to the stem",body:"The histogram lets the team compare the shape with the normal curve while reading the statistics."}],final:"Histogram with normal curve → answer **A**",whyWrong:["","Incorrect — a Pareto chart ranks categories; it does not show the shape of a continuous variable.","Incorrect — a control chart checks stability over time, not the distribution's shape.","Incorrect — a scatterplot shows a relationship between two variables."],bookRef:"Book p. 148"},{id:"sv-2-906",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about the mean and the median is CORRECT?",options:["The mean is unaffected by large data values, but the median is not","The median is unaffected by large data values, but the mean is not","The mean and the median are always equal","The median is the arithmetic balance point of the data"],answer:1,hint:"Which one does a billionaire move?",steps:[{title:"Key idea",body:"Book p. 148: the median is the physical centre and **unaffected by large data values**; the mean is the balance point and is pulled by them."},{title:"Eliminate look-alikes",body:"The two differ whenever the data are skewed."}],final:"Median resists extremes; mean does not → answer **B**",whyWrong:["Incorrect — reversed: extreme values pull the mean, not the median.","","Incorrect — they are equal only for symmetrical data; extremes separate them.","Incorrect — the balance point is the mean; the median is the physical centre."],bookRef:"Book p. 148"},{id:"sv-2-907",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about the mode is CORRECT?",options:["The mode is always equal to the median","The mode is the arithmetic balance point","A data set can have more than one mode","The mode cannot be used for nominal data"],answer:2,hint:"Can two values tie for 'most frequent'?",steps:[{title:"Key idea",body:'Book p. 149: "It is possible to have multiple Modes" — a bi-modal distribution.'},{title:"Eliminate look-alikes",body:"The balance point is the mean; the mode suits nominal data."}],final:"Multiple modes are possible → answer **C**",whyWrong:["Incorrect — the mode equals the median only in some distributions, such as symmetric unimodal ones.","Incorrect — the balance point is the mean.","","Incorrect — the mode is the one centre measure that works for nominal categories."],bookRef:"Book p. 149"},{id:"sv-2-908",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about the **sample mean** and the **population mean** is CORRECT?",options:["The sample mean divides the total by n − 1","The population mean is found from the median","The sample mean is always smaller than the population mean","They are calculated the same way; only the symbol differs"],answer:3,hint:"x̄ versus μ — what changes?",steps:[{title:"Key idea",body:'Book p. 148: "Although the symbol is different there is no mathematical difference between the Mean of a sample and Mean of a population."'},{title:"Eliminate look-alikes",body:"The n − 1 divisor belongs to s and s²."}],final:"Same formula, different symbol → answer **D**",whyWrong:["Incorrect — n − 1 is used in the sample standard deviation and variance, not the mean.","Incorrect — both means are arithmetic averages; neither uses the median.","Incorrect — a sample mean can fall above or below the population mean.",""],bookRef:"Book p. 148",trap:"n − 1 is for the sample SD/variance, not the mean."},{id:"sv-2-909",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about the **trimmed mean** is CORRECT?",options:["It is a compromise between the mean and the median","It is a compromise between the median and the mode","It is always equal to the median of the data","It is more affected by extreme scores than the mean"],answer:0,hint:"Part average, part resistant.",steps:[{title:"Key idea",body:"Book p. 149: the trimmed mean is a **compromise between the mean and the median**, useful for data with potential extreme values."},{title:"Eliminate look-alikes",body:"It is less, not more, susceptible to extremes than the mean."}],final:"Trimmed mean = mean/median compromise → answer **A**",whyWrong:["","Incorrect — the mode plays no part; the trimmed mean sits between mean and median.","Incorrect — it still averages many values, so it usually differs from the median.","Incorrect — reversed: trimming the extremes makes it less affected than the mean."],bookRef:"Book p. 149"},{id:"sv-2-910",phase:2,topic:"2.2.2",qtype:"concept",difficulty:2,stem:"Which statement about combining the variation of **independent** sources is CORRECT?",options:["The standard deviation of the total is the sum of the sources' standard deviations","The variance of the total is the sum of the sources' variances","The variance of the total equals the largest source variance","Standard deviations can be added if they share the same units"],answer:1,hint:"Which quantity is additive?",steps:[{title:"Key idea",body:'Book p. 150: "Standard Deviations cannot be added, variances can."'},{title:"Apply to the stem",body:"For independent sources, total variance = sum of variances; this is the basis of Gage R&R."}],final:"Total variance = sum of variances → answer **B**",whyWrong:["Incorrect — SDs cannot be added; the total SD is the square root of the summed variances.","","Incorrect — every independent source contributes, so the total exceeds the largest variance.","Incorrect — shared units do not make SDs additive; only variances add."],bookRef:"Book p. 150"},{id:"sv-2-911",phase:2,topic:"2.2.2",qtype:"statements",difficulty:2,stem:`Which statements about measures of location are CORRECT?

1. The median is the arithmetic balance point of the data.
2. The trimmed mean removes extreme values before averaging.
3. The mode is the most frequently occurring value.
4. The mean is unaffected by extreme values.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Check each definition against the book.",steps:[{title:"Key idea",body:"Mean = balance point (pulled by extremes); median = middle; mode = most frequent; trimmed mean = average after trimming."},{title:"Apply to the stem",body:"Statements 2 and 3 are true."}],final:"2 and 3 → answer **B**",whyWrong:["Incorrect — statement 2 is true, but the balance point is the mean, not the median.","","Incorrect — statement 3 is true, but extreme values do pull the mean.","Incorrect — both are false: the balance point is the mean, and the mean is pulled by extremes."],bookRef:"Book pp. 148–149"},{id:"sv-2-912",phase:2,topic:"2.2.2",qtype:"statements",difficulty:2,stem:`Which statements about kurtosis are CORRECT?

1. Kurtosis refers to the shape of the tails.
2. A leptokurtic distribution is flat with short tails.
3. A negative kurtosis value indicates a leptokurtic distribution.
4. A platykurtic distribution is flat with short tails.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Lepto = peaked, long tails (+); platy = flat, short tails (−).",steps:[{title:"Key idea",body:"Book pp. 260–261: kurtosis = shape of the tails; leptokurtic peaked/long tails (+); platykurtic flat/short tails (−)."},{title:"Apply to the stem",body:"Statements 1 and 4 are true."}],final:"1 and 4 → answer **D**",whyWrong:["Incorrect — statement 1 is true, but leptokurtic means peaked with long tails.","Incorrect — both are false: leptokurtic is peaked with long tails and has positive kurtosis.","Incorrect — statement 4 is true, but negative kurtosis indicates platykurtic, not leptokurtic.",""],bookRef:"Book pp. 260–261"},{id:"sv-2-913",phase:2,topic:"2.2.2",qtype:"statements",difficulty:2,stem:`Which statements about measures of variation are CORRECT?

1. Standard deviations of independent sources can be added.
2. The variance is the square of the standard deviation.
3. The range or IQR should be used when the data are skewed.
4. The standard deviation is the best measure for skewed data.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Variances add; SD for symmetry; range/IQR for skew.",steps:[{title:"Key idea",body:"Book pp. 150–151: variance = SD squared, and variances (not SDs) add; range or IQR for skewed data; SD for symmetrical data."},{title:"Apply to the stem",body:"Statements 2 and 3 are true."}],final:"2 and 3 → answer **B**",whyWrong:["Incorrect — statement 2 is true, but standard deviations cannot be added.","","Incorrect — statement 3 is true, but the SD suits symmetrical, not skewed, data.","Incorrect — both are false: SDs cannot be added, and the SD suits symmetrical data."],bookRef:"Book pp. 150–151"},{id:"sv-2-914",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

The [?] is the physical centre of a data set and is unaffected by large data values.`,options:["mean","median","mode","range"],answer:1,hint:"Middle of the ordered data.",steps:[{title:"Key idea",body:'Book p. 148: "The physical center of a data set is the **Median** and unaffected by large data values."'},{title:"Eliminate look-alikes",body:"Mean = balance point; mode = most frequent; range = spread."}],final:"median → answer **B**",whyWrong:["Incorrect — the mean is the balance point and is pulled by large values.","","Incorrect — the mode is the most frequent value, not the physical centre.","Incorrect — the range is a spread measure, and it is driven by the extremes."],bookRef:"Book p. 148"},{id:"sv-2-915",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A small [?] indicates a small amount of variability, and a large one a large amount of variability.`,options:["mean","median","mode","range"],answer:3,hint:"Largest minus smallest.",steps:[{title:"Key idea",body:"Book p. 150: the range is the difference between the largest and smallest observations; a small range indicates a small amount of variability."},{title:"Eliminate look-alikes",body:"Mean, median and mode are measures of location."}],final:"range → answer **D**",whyWrong:["Incorrect — the mean locates the centre; its size says nothing about spread.","Incorrect — the median locates the centre, not the spread.","Incorrect — the mode is the most frequent value, a location measure.",""],bookRef:"Book p. 150"},{id:"sv-2-916",phase:2,topic:"2.2.2",qtype:"missing-word",difficulty:2,stem:`Identify the missing word in the following sentence.

[?] distributions occur when data come from several sources that are supposed to be the same but are not.`,options:["Mixed","Normal","Truncated","Uniform"],answer:0,hint:"Machine A + Machine B, Operator A + Operator B.",steps:[{title:"Key idea",body:'Book p. 257: "Mixed Distributions occur when data comes from multiple sources that are supposed to be the same yet are not" — machines, operators, payment methods, interviewers.'},{title:"Apply to the stem",body:"So the missing word is Mixed."}],final:"Mixed → answer **A**",whyWrong:["","Incorrect — a normal distribution comes from one source with only random error.","Incorrect — truncated distributions come from cutting values off (sorting), not from several sources.","Incorrect — a uniform distribution has all values equally likely; it is not defined by sources."],bookRef:"Book p. 257"},{id:"sv-2-917",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:2,stem:"Which is NOT a reason for multiple modes given in the book?",options:["A mixture of distributions from different sources","Lack of independence, such as trends or patterns","Collecting a larger sample from the same stable process","Catastrophic failures, such as a motor shorting out"],answer:2,hint:"Which option adds no new source of variation?",steps:[{title:"Key idea",body:"Book p. 261: reasons for multiple modes — mixtures (most likely), lack of independence, catastrophic failures."},{title:"Apply to the stem",body:"More data from the same stable process sharpens its single shape; it does not create new modes."}],final:"Larger sample ≠ cause of modes → answer **C**",whyWrong:["Incorrect — a mixture of distributions is the book's most likely reason for multiple modes.","Incorrect — trends or patterns (lack of independence) are a listed reason.","","Incorrect — catastrophic failures, such as zero readings from a shorted motor, are a listed reason."],bookRef:"Book p. 261"},{id:"sv-2-918",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:2,stem:"In which situation would the median NOT be preferred to the mean as the summary of the centre?",options:["Household incomes that include a few billionaires","Complaint-closure times with a few cases open for months","Repair costs where a handful of jobs cost fifty times the rest","Fill weights from a stable line that are symmetrical with no outliers"],answer:3,hint:"When do the mean and the median tell the same story?",steps:[{title:"Key idea",body:"Book pp. 148–151: the median resists extreme values; for symmetrical data the mean (with the SD) is appropriate."},{title:"Apply to the stem",body:"Symmetrical fill weights with no outliers — the mean is fine. The other three are skewed."}],final:"Symmetrical data → mean is fine → answer **D**",whyWrong:["Incorrect — a few extreme incomes pull the mean, so the median is preferred.","Incorrect — months-long cases skew the data, so the median is preferred.","Incorrect — a handful of extreme costs pull the mean, so the median is preferred.",""],bookRef:"Book pp. 148–151"},{id:"sv-2-919",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:3,stem:"Which is NOT a cause of a **platykurtic** (flat) distribution given in the book?",options:["A single process with only random error","Data combined from multiple machines or set-ups","Tool wear causing the mean to drift over time","Scrapping product that falls outside the spec limits"],answer:0,hint:"What gives a normal shape instead?",steps:[{title:"Key idea",body:"Book p. 260: multiple means shifting over time produce a plateau — causes include mixtures, sorting, trends and non-linear relationships."},{title:"Apply to the stem",body:"A single process with only random error gives a normal shape, not a flat one."}],final:"Random error only → normal, not flat → answer **A**",whyWrong:["","Incorrect — mixtures of machines or set-ups are a listed cause of a flat shape.","Incorrect — tool wear (a trend over time) is a listed cause.","Incorrect — sorting or selecting by scrapping out-of-spec product is a listed cause."],bookRef:"Book p. 260"},{id:"sv-2-920",phase:2,topic:"2.2.2",qtype:"not-except",difficulty:2,stem:"All of the following describe the **standard deviation** EXCEPT:",options:["It is a unit of measure for distances from the mean","It is the best spread measure for strongly skewed data","It is the square root of the variance","It is equivalent to the average deviation of values from the mean"],answer:1,hint:"When does the book say to use the SD?",steps:[{title:"Key idea",body:"Book p. 151: SD = average deviation from the mean, a unit of measure for distances; use when data are **symmetrical**."},{title:"Apply to the stem",body:"For skewed data the book recommends the range or IQR — the outsider."}],final:"SD is not for skewed data → answer **B**",whyWrong:["Incorrect — the book calls the SD a unit of measure for distances from the mean.","","Incorrect — the variance is the square of the SD, so the SD is its square root.","Incorrect — the book describes the SD as the equivalent of the average deviation from the mean."],bookRef:"Book pp. 150–151"},{id:"sv-2-921",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:3,stem:"A data logger on a curing oven occasionally records a spurious spike when its cable is knocked. The Black Belt wants a centre measure that still averages most of the readings but is less affected by these spikes. Which measure fits BEST?",options:["Mean","Mode","Trimmed mean","Range"],answer:2,hint:"Average most values, drop the extremes.",steps:[{title:"Key idea",body:"Book p. 149: the trimmed mean is a compromise between mean and median, useful for data with potential extreme values."},{title:"Apply to the stem",body:"It still averages the bulk of the readings while trimming the spikes."}],final:"Trimmed mean → answer **C**",whyWrong:["Incorrect — the ordinary mean includes every spike and is pulled by them.","Incorrect — the mode uses only the most frequent value, not an average of most readings.","","Incorrect — the range is a spread measure and is driven by the spikes."],bookRef:"Book p. 149"},{id:"sv-2-922",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:3,stem:"Pack weights from three filling machines are pooled in one data set. The histogram is flat-topped with short tails, and Minitab reports **Kurtosis = −0.99**. How should the Black Belt classify the shape and its likely cause?",options:["Leptokurtic, probably very different variances overlaid","Normal, because the kurtosis is close to −1","Right-skewed, probably caused by sorting at an upper limit","Platykurtic, probably a mixture of the three machines' outputs"],answer:3,hint:"Negative kurtosis, several sources.",steps:[{title:"Key idea",body:"Book p. 260: negative kurtosis → **platykurtic**; mixtures of multiple machines, set-ups or batches are a listed cause."},{title:"Apply to the stem",body:"Three machines with slightly different means pooled together form a plateau."}],final:"Platykurtic from mixture → answer **D**",whyWrong:["Incorrect — leptokurtic needs a positive kurtosis and a peaked, long-tailed shape.","Incorrect — a normal shape has kurtosis near zero, not near −1.","Incorrect — skew is read from skewness; kurtosis describes the tails.",""],bookRef:"Book p. 260"},{id:"sv-2-923",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:1,stem:"A store manager wants to know which handset colour customers buy most often, so she can stock the right shelves. Which measure of location answers her question?",options:["Mean","Median","Mode","Trimmed mean"],answer:2,hint:"Most often = ?",steps:[{title:"Key idea",body:"Book p. 149: the mode is the **most frequently occurring** value."},{title:"Apply to the stem",body:"Colour is nominal; the mode is the only centre measure that applies."}],final:"Most frequent colour = mode → answer **C**",whyWrong:["Incorrect — colours are labels with no numeric value to average.","Incorrect — colours have no natural order, so there is no middle value.","","Incorrect — a trimmed mean still needs numeric values to average."],bookRef:"Book p. 149"},{id:"sv-2-924",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:2,stem:"Customers rate a field visit from **1 (very poor) to 5 (excellent)**. The Black Belt needs one figure for the typical rating that respects the type of data. Which measure of location should she report?",options:["Median, because the ratings are ordered but the gaps are not exact","Mean, because the ratings are numbers that can be averaged","Trimmed mean, because ratings of 1 are extreme values","Mode only, because ratings are nominal labels"],answer:0,hint:"Ordered categories → middle value.",steps:[{title:"Key idea",body:"Ratings are **ordinal**: ordered, but differences have no exact meaning (Book pp. 144–145)."},{title:"Apply to the stem",body:"The median uses only the order, so it is the right centre measure for ordinal data."}],final:"Ordinal → median → answer **A**",whyWrong:["","Incorrect — rating codes are ordinal; averaging assumes equal gaps that do not exist.","Incorrect — a rating of 1 is a legitimate response, not an extreme value to trim.","Incorrect — the ratings have a natural order, so they are ordinal, not nominal."],bookRef:"Book pp. 144–148"},{id:"sv-2-925",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:2,stem:"Surface roughness readings on machined shafts are skewed by occasional deep scratches. The Black Belt reports the median as the centre. Which spread measure should accompany it?",options:["Standard deviation","Interquartile range","Variance","Standard error of the mean"],answer:1,hint:"Pair a robust centre with a robust spread.",steps:[{title:"Key idea",body:"Book p. 150: use the range or **interquartile range** when the distribution is skewed."},{title:"Apply to the stem",body:"The IQR covers the middle 50% and ignores the scratch-driven tail."}],final:"Skewed → median + IQR → answer **B**",whyWrong:["Incorrect — the SD is inflated by the scratches and suits symmetrical data.","","Incorrect — the variance squares the scratch deviations, so it is even more inflated.","Incorrect — SE Mean measures the precision of the mean, not the spread of the readings."],bookRef:"Book p. 150"},{id:"sv-2-926",phase:2,topic:"2.2.2",qtype:"scenario",difficulty:2,stem:"A Black Belt checks the book's descriptive questions for a new data set and finds that the **mean, median and mode are almost identical**. What does this suggest about the data?",options:["The distribution is strongly right-skewed","The distribution must be bimodal","The distribution is roughly symmetrical","The data contain several extreme high values"],answer:2,hint:"When do the three measures coincide?",steps:[{title:"Key idea",body:"Book p. 147: ask how alike the measures of location are and what that tells you."},{title:"Apply to the stem",body:"When mean ≈ median ≈ mode, nothing is pulling the mean away: the data are roughly symmetrical."}],final:"Mean ≈ median ≈ mode → symmetrical → answer **C**",whyWrong:["Incorrect — right skew pulls the mean above the median.","Incorrect — a bimodal distribution has two modes, usually away from the mean.","","Incorrect — extreme high values would pull the mean away from the median."],bookRef:"Book pp. 147–149"},{id:"sv-2-927",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:3,stem:"Two vendors send monthly reports on strongly right-skewed resolution times. Vendor A reports the **mean**; Vendor B reports the **median**. The Champion wants to know which vendor is faster. What is the BEST action FIRST?",options:["Compare the two figures directly, because both describe the centre","Declare Vendor B faster, because a median is always smaller","Average the two figures to get a fair common baseline","Obtain the same measure of location from both vendors before comparing"],answer:3,hint:"Compare like with like.",steps:[{title:"Key idea",body:"Book p. 148: extreme values pull the mean but not the median, so in skewed data the two can differ greatly."},{title:"Apply to the stem",body:"Ask both vendors for the same statistic (ideally the median, with the raw data) before any comparison."}],final:"Same statistic before comparing → answer **D**",whyWrong:["Incorrect — for skewed data the mean sits well above the median, so the figures are not comparable.","Incorrect — the median is often smaller for right-skewed data, but that says nothing about the vendors.","Incorrect — averaging a mean with a median mixes two different statistics.",""],bookRef:"Book pp. 148–150"},{id:"sv-2-928",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:1,stem:'A baseline report for ticket resolution states only: *"Mean resolution time 37 min."* What is the BEST action before the Champion signs it off?',options:["Add a measure of variation, such as the standard deviation or IQR","Add the mode so that three location measures are shown","Replace the mean with the maximum resolution time","Report the mean to more decimal places for accuracy"],answer:0,hint:"Location alone hides half the picture.",steps:[{title:"Key idea",body:"Book p. 147: descriptive statistics come in two families — location **and** variation."},{title:"Apply to the stem",body:"Two processes with the same 37-minute mean can have very different spreads, so report one."}],final:"Report spread with the centre → answer **A**",whyWrong:["","Incorrect — more location measures still say nothing about spread.","Incorrect — the maximum is a single extreme value, not a summary of spread.","Incorrect — extra decimals add precision to the centre but no information on variation."],bookRef:"Book p. 147"},{id:"sv-2-929",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:3,stem:'Ticket data include one **400-hour** outage. To make the mean look "typical", a Black Belt deletes it without noting why. Was this an appropriate action?',options:["Yes, because an extreme value always distorts descriptive statistics","Yes, because the mean must represent the typical ticket","No, because the outage should be replaced by the mean of the other tickets","No, because the value should be investigated; a median or trimmed mean can describe the centre without hiding it"],answer:3,hint:"Choose the measure, keep the data.",steps:[{title:"Key idea",body:"Book pp. 148–149: the median is unaffected by large values; the trimmed mean is less susceptible to extremes."},{title:"Apply to the stem",body:"Keep and investigate the outage, and use a robust centre measure for 'typical'."}],final:"Investigate; use a robust measure → answer **D**",whyWrong:["Incorrect — distortion of the mean is a reason to choose a robust measure, not to delete data.","Incorrect — a robust measure gives a typical value without deleting real data.","Incorrect — replacing a real value with an average invents data and hides the event.",""],bookRef:"Book pp. 148–149"},{id:"sv-2-930",phase:2,topic:"2.2.2",qtype:"best-action",difficulty:2,stem:"Invoice-handling times come from two teams that are supposed to follow the same procedure. Their separate summaries show different centres. What is the BEST action before building a single baseline?",options:["Combine the teams, because a larger data set is always more reliable","Analyse the teams separately, because combining them would form a mixed distribution","Report only the faster team as the baseline","Report the overall mean, because it balances the two teams"],answer:1,hint:"Sources that should be the same, but are not.",steps:[{title:"Key idea",body:"Book p. 257: mixed distributions occur when data come from several sources that are supposed to be the same but are not."},{title:"Apply to the stem",body:"Describe each team on its own first; the difference itself is a lead for Analyze."}],final:"Separate the sources first → answer **B**",whyWrong:["Incorrect — pooling two different sources hides the difference and distorts the shape.","","Incorrect — dropping one team gives a baseline that does not describe the process.","Incorrect — one overall mean may describe neither team well."],bookRef:"Book p. 257"},{id:"sv-2-931",phase:2,topic:"2.2.2",qtype:"output",difficulty:1,stem:`Minitab output for 200 shaft diameters:

\`\`\`
Descriptive Statistics: Diameter
Variable    N    Mean    StDev   Median   Mode
Diameter  200  4.9999   0.0101   5.0000      5
\`\`\`

Which statement is CORRECT?`,options:["The mean is far above the median, so the data are right-skewed","The data are bimodal, because both a median and a mode are reported","The mean, median and mode agree, so the data are centred and roughly symmetrical","The standard deviation cannot be used, because the mode is a whole number"],answer:2,hint:"Compare the three location measures.",steps:[{title:"Key idea",body:"Book pp. 148–149: mean 4.9999, median 5.0000, mode 5 — the measures of location agree."},{title:"Apply to the stem",body:"Agreement indicates a symmetrical distribution, where the SD is the right spread measure."}],final:"Location measures agree → symmetrical → answer **C**",whyWrong:["Incorrect — the mean (4.9999) and median (5.0000) are practically equal.","Incorrect — Minitab reports one mode, 5; two printed statistics do not mean two modes.","","Incorrect — the format of the mode has no bearing on using the SD for symmetrical data."],bookRef:"Book pp. 148–149"},{id:"sv-2-932",phase:2,topic:"2.2.2",qtype:"output",difficulty:2,stem:`Minitab output for bottle fill volumes:

\`\`\`
Descriptive Statistics: FillMl
Variable    N     Mean   TrMean   Median
FillMl    150   500.21   500.20   500.20
\`\`\`

Which conclusion is CORRECT?`,options:["The mean is distorted by extreme values and should be replaced by the median","The trimmed mean has removed most of the data, so it cannot be trusted","The data must be bimodal, because three location measures are printed","Extreme values have no material effect, so the mean is a fair summary of the centre"],answer:3,hint:"Compare Mean with TrMean.",steps:[{title:"Key idea",body:"Book p. 149: the trimmed mean is less susceptible to extreme scores; in the book's own output TrMean equals the mean."},{title:"Apply to the stem",body:"Mean ≈ TrMean ≈ Median here, so no extreme values are pulling the mean."}],final:"Mean ≈ TrMean → no extreme influence → answer **D**",whyWrong:["Incorrect — the mean (500.21) is practically equal to the trimmed mean and median.","Incorrect — trimming removes only a small percentage from each end.","Incorrect — the number of printed statistics says nothing about the number of modes.",""],bookRef:"Book p. 149"},{id:"sv-2-933",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Minitab output for one gasket thickness measured on two presses:

\`\`\`
Variable    Press      N    Mean   StDev   Kurtosis
Thickness   P1       100    2.50    0.02      0.05
Thickness   P2       100    2.50    0.12     -0.10
Thickness   Pooled   200    2.50    0.09      3.60
\`\`\`

Which conclusion is CORRECT?`,options:["Pooling two presses with very different spreads has produced a leptokurtic shape","Pooling two presses with different means has produced a platykurtic shape","Each press is leptokurtic, so the pooled data must also be leptokurtic","The pooled data are normal, because the two means are the same"],answer:0,hint:"Same centres, different spreads, overlaid.",steps:[{title:"Key idea",body:"Book p. 261: distributions overlaying each other with very different variances can cause a **leptokurtic** distribution (positive kurtosis)."},{title:"Apply to the stem",body:"P1 and P2 are near-normal; pooled kurtosis +3.60 shows a peaked, long-tailed mixture."}],final:"Different variances overlaid → leptokurtic → answer **A**",whyWrong:["","Incorrect — the means are equal (2.50); the presses differ in spread, and the pooled kurtosis is positive.","Incorrect — each press has kurtosis near zero; only the pooled data are peaked with long tails.","Incorrect — equal means do not prevent a non-normal shape when spreads differ greatly."],bookRef:"Book p. 261"},{id:"sv-2-934",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`A Black Belt summarised two independent stages of an activation process:

\`\`\`
Stage                       StDev (h)   Variance (h²)
Validate                        3.0          9.0
Provision                       4.0         16.0
Sum of stage values             7.0         25.0
End-to-end (measured)           5.0         25.0
\`\`\`

Which conclusion does the table support?`,options:["The stage standard deviations add up to the end-to-end standard deviation","The stage variances add up to the end-to-end variance, but the stage standard deviations do not","Neither the variances nor the standard deviations of the stages add up","The end-to-end variation was measured wrongly because 5.0 is not 7.0"],answer:1,hint:"Compare the 'Sum' row with the 'End-to-end' row.",steps:[{title:"Key idea",body:'Book p. 150: "Standard Deviations cannot be added, variances can."'},{title:"Apply to the stem",body:"Variance column: 25.0 = 25.0. StDev column: 7.0 ≠ 5.0."}],final:"Variances add; SDs don't → answer **B**",whyWrong:["Incorrect — the printed sum of SDs (7.0) differs from the measured end-to-end SD (5.0).","","Incorrect — the printed sum of variances (25.0) matches the end-to-end variance (25.0).","Incorrect — 5.0 is expected: standard deviations are not additive."],bookRef:"Book p. 150"},{id:"sv-2-935",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Binned results of a motor voltage test:

\`\`\`
Voltage bin (V)   Count
0 – 10               14
10 – 200              0
200 – 220            22
220 – 240           161
240 – 260            23
\`\`\`

The 14 low readings come from motors that shorted out during the test. Which book reason for multiple modes does the low group reflect?`,options:["Catastrophic failures","Lack of independence","Mixtures of distributions","Natural limits"],answer:0,hint:"The book's own example uses a shorted motor.",steps:[{title:"Key idea",body:'Book p. 261: reasons for multiple modes include **catastrophic failures** — "testing voltage on a motor and the motor shorts out so we get a zero reading".'},{title:"Apply to the stem",body:"The 0–10 V group is exactly that failure mode, separate from the main peak."}],final:"Shorted motors = catastrophic failures → answer **A**",whyWrong:["","Incorrect — lack of independence shows as trends or patterns over time, not a block of zero readings.","Incorrect — a mixture is two sources of the same output; here units failed outright and read zero.","Incorrect — natural limits cause skew near a bound; they do not create a separate group of failures."],bookRef:"Book p. 261"},{id:"sv-2-936",phase:2,topic:"2.2.2",qtype:"output",difficulty:1,stem:`Minitab output for fault-repair times in two regions:

\`\`\`
Descriptive Statistics: RepairMin
Variable   Region    N   Mean   StDev
RepairMin  East     60   37.0     4.2
RepairMin  West     60   37.0    15.8
\`\`\`

Which statement is CORRECT?`,options:["Both regions perform identically because their means are equal","East has more variation because its standard deviation is smaller","Both regions have the same centre, but West has much more variation","West has a higher centre because its standard deviation is larger"],answer:2,hint:"Location and variation are different families.",steps:[{title:"Key idea",body:"Book p. 147: measures of location (mean) and of variation (SD) answer different questions."},{title:"Apply to the stem",body:"Means are both 37.0; West's SD of 15.8 is far larger than East's 4.2."}],final:"Same mean, West more variable → answer **C**",whyWrong:["Incorrect — equal means hide very different spreads; location alone is not enough.","Incorrect — a smaller standard deviation means less variation, not more.","","Incorrect — the standard deviation measures spread, not the centre."],bookRef:"Book p. 147"},{id:"sv-2-937",phase:2,topic:"2.2.2",qtype:"output",difficulty:3,stem:`Minitab output for call-answer times in one queue, on one system, with no values screened out:

\`\`\`
Descriptive Statistics: AnswerSec
Variable     N   Mean   Median   Minimum   Maximum   Skewness
AnswerSec  240   14.2      9.0       0.0      96.0       2.31
\`\`\`

Which cause of skewness does this MOST likely reflect?`,options:["An artificial limit, because values were sorted out at inspection","A mixture, because the data came from several queues","Only random error, because the skewness is positive","A natural limit, because an answer time cannot fall below zero"],answer:3,hint:"Where is the hard boundary?",steps:[{title:"Key idea",body:"Book p. 257: natural limits are a cause of skewness — values pile up against a bound they cannot cross."},{title:"Apply to the stem",body:"Minimum 0.0, median 9.0 and a long tail to 96.0 (skewness +2.31) fit a zero bound with no other source."}],final:"Zero bound → natural-limit skew → answer **D**",whyWrong:["Incorrect — the stem says no values were screened out, so there is no artificial limit.","Incorrect — the stem says one queue on one system, so no mixture of sources.","Incorrect — a skewness of 2.31 is far from the near-zero value of a symmetric, random-only process.",""],bookRef:"Book p. 257"},{id:"sv-2-938",phase:2,topic:"2.2.2",qtype:"true-false",difficulty:1,stem:"The trimmed mean is less susceptible to the effects of extreme scores than the ordinary mean. True or False?",options:["True","False"],answer:0,hint:"What does trimming remove?",steps:[{title:"Key idea",body:'Book p. 149: "The trimmed Mean … is less susceptible to the effects of extreme scores."'},{title:"Apply to the stem",body:"So the statement is true."}],final:"True → answer **True**",whyWrong:["","Incorrect — trimming removes the smallest and largest values, so extremes have less effect."],bookRef:"Book p. 149"},{id:"sv-2-939",phase:2,topic:"2.2.2",qtype:"sequence",difficulty:1,stem:`Put these steps in order to find the median of a data set with an **even** number of values.

- **P** Average the two middle values
- **Q** Arrange the data from low to high
- **R** Locate the two middle values`,options:["Q → R → P","R → Q → P","Q → P → R","P → Q → R"],answer:0,hint:"Order, locate, average.",steps:[{title:"Key idea",body:"Book p. 148: arrange the data low to high; with an even count the median is the average of the two middle values."},{title:"Apply to the stem",body:"So Q, R, P."}],final:"Q → R → P → answer **A**",whyWrong:["","Incorrect — the middle values cannot be found until the data are ordered.","Incorrect — the two middle values must be located before they are averaged.","Incorrect — averaging comes last, after ordering and locating."],bookRef:"Book p. 148"},{id:"sv-2-940",phase:2,topic:"2.2.2",qtype:"sequence",difficulty:2,stem:`Order the steps to combine the variation of two **independent** stages into one standard deviation.

- **S** Take the square root of the total
- **T** Square each stage's standard deviation to get its variance
- **U** Add the variances`,options:["U → T → S","T → U → S","S → T → U","T → S → U"],answer:1,hint:"Variances add — so get variances first.",steps:[{title:"Key idea",body:"Book p. 150: standard deviations cannot be added, variances can."},{title:"Apply to the stem",body:"Square each SD (variance) → add the variances → square-root the total: T, U, S."}],final:"T → U → S → answer **B**",whyWrong:["Incorrect — the variances must exist before they can be added.","","Incorrect — the square root is taken last, on the total variance.","Incorrect — taking the root before adding brings back the SDs, which cannot be added."],bookRef:"Book p. 150"}];export{e as items};
